// Systems theme — P4 Science
// Ch.9: The Human Body As A System | Ch.10: The Digestive System
// Ch.11: Respiratory & Circulatory | Plant Transport | Electrical Circuits
window.QUIZ_DATA = window.QUIZ_DATA || {};
window.QUIZ_DATA.systems = {

ch1: [
  // Chapter 9: What Is A System? + The 5 Organ Systems
  { q: "What is a system?", opts: ["Two or more parts that work together to carry out a function", "A single part that works on its own", "Any living thing", "A machine that uses electricity"], ans: 0, explain: "A system is made up of two or more parts that function together to carry out a certain function." },
  { q: "What is the minimum number of parts needed to make a system?", opts: ["Two", "One", "Three", "Five"], ans: 0, explain: "A system is made up of two or more parts. A single part on its own is not a system." },
  { q: "Is a ruler a system?", opts: ["No — a ruler is made up of only one part", "Yes — a ruler has markings, so it has many parts", "Yes — a ruler is used to measure, so it must be a system", "No — only living things can be systems"], ans: 0, explain: "A ruler is made up of only one part. Since a system needs two or more parts working together, a ruler is not a system." },
  { q: "What happens if one part of a system is damaged or does not work correctly?", opts: ["The system will not be able to carry out its function properly", "The other parts work harder and make up for the missing part", "The system works better with fewer parts", "Nothing changes — the other parts are unaffected"], ans: 0, explain: "If one part of a system is damaged or does not work correctly, the system will not be able to carry out its function properly." },
  { q: "A torch has a bulb, a battery, a switch and a casing. If the bulb is spoilt, what happens?", opts: ["The torch will not light up — a damaged part means the system cannot function properly", "The torch still lights up using the other parts", "The battery powers the torch directly without the bulb", "The switch takes over the role of the bulb"], ans: 0, explain: "The torch is a man-made system. If any part (such as the bulb) is spoilt, the system cannot carry out its function — the torch will not produce light." },
  { q: "A torch is an example of a ___ system.", opts: ["Man-made", "Natural", "Living", "Plant"], ans: 0, explain: "A torch is an example of a man-made system. It is made up of parts (bulb, battery, switch, casing) that work together to produce light." },
  { q: "The human body is an example of a ___ system.", opts: ["Natural", "Man-made", "Electrical", "Mechanical"], ans: 0, explain: "Living things, including the human body, are examples of natural systems. Their parts have specific functions and work together to keep the organism alive and healthy." },
  { q: "How many main organ systems in the human body are covered in this chapter?", opts: ["Five", "Two", "Three", "Seven"], ans: 0, explain: "Five organ systems are covered: the digestive, respiratory, circulatory, skeletal and muscular systems." },
  { q: "What is the function of the digestive system?", opts: ["Breaks down food into simple substances and absorbs nutrients for the body", "Transports oxygen to all parts of the body", "Supports the body and gives it shape", "Enables different parts of the body to move"], ans: 0, explain: "The digestive system breaks down food into simple substances, absorbs digested food, nutrients, minerals and water for the body to use, and stores undigested food until it is removed." },
  { q: "What are the parts of the digestive system?", opts: ["Mouth, gullet, stomach, small intestine, large intestine and anus", "Nose, windpipe and lungs", "Heart, blood vessels and blood", "Skull, ribs and back bone"], ans: 0, explain: "The digestive system is made up of the mouth, gullet, stomach, small intestine, large intestine and anus." },
  { q: "What is the function of the respiratory system?", opts: ["Takes in air (oxygen) into the body and removes air (carbon dioxide) from the body", "Breaks down food into simple substances", "Transports oxygen and nutrients to all parts of the body", "Supports the body and protects delicate organs"], ans: 0, explain: "The respiratory system takes in air (oxygen) into the body and removes air (carbon dioxide) from the body." },
  { q: "What are the parts of the respiratory system?", opts: ["Nose, windpipe and lungs", "Mouth, gullet and stomach", "Heart, blood vessels and blood", "Muscles in the body"], ans: 0, explain: "The respiratory system is made up of the nose, windpipe and lungs." },
  { q: "What is the function of the circulatory system?", opts: ["Transports oxygen, digested food, nutrients, minerals and water to all parts of the body, and carries waste materials away", "Takes in oxygen and removes carbon dioxide", "Breaks down food into simpler substances", "Enables different parts of the body to move"], ans: 0, explain: "The circulatory system transports oxygen, digested food, nutrients, minerals and water to different parts of the body. It also transports waste materials away from different parts of the body." },
  { q: "What are the parts of the circulatory system?", opts: ["Heart, blood vessels and blood", "Nose, windpipe and lungs", "Mouth, gullet and stomach", "Skull, ribs and back bone"], ans: 0, explain: "The circulatory system is made up of the heart, blood vessels and blood." },
  { q: "What are the functions of the skeletal system?", opts: ["Supports the body and gives it shape; protects delicate organs like the heart and lungs", "Enables different parts of the body to move", "Transports oxygen and nutrients to all parts of the body", "Breaks down food into simpler substances"], ans: 0, explain: "The skeletal system supports the body and gives it shape, and protects delicate organs such as the heart and lungs." },
  { q: "What are the parts of the skeletal system?", opts: ["Bones such as the skull, ribs and back bone", "Muscles in the body", "Heart, blood vessels and blood", "Nose, windpipe and lungs"], ans: 0, explain: "The skeletal system is made up of bones, including the skull, ribs and back bone." },
  { q: "What is the function of the muscular system?", opts: ["Enables different parts of the body to move", "Supports the body and gives it shape", "Transports nutrients to all parts of the body", "Takes in oxygen and removes carbon dioxide"], ans: 0, explain: "The muscular system enables different parts of the body to move." },
  { q: "What are the parts of the muscular system?", opts: ["Muscles in the body", "Bones such as the skull and ribs", "Heart, blood vessels and blood", "Nose, windpipe and lungs"], ans: 0, explain: "The muscular system is made up of the muscles in the body." },
  { q: "All human body systems are ___. If any one system fails, the others will be affected.", opts: ["Interconnected", "Completely independent of each other", "Made of the same parts", "Identical in function"], ans: 0, explain: "All human systems are interconnected. They work together to enable the body to function properly. If any system fails, the other systems will be affected and may subsequently fail too." },
  { q: "The digestive system provides digested food. Which system carries this food to all parts of the body?", opts: ["The circulatory system", "The respiratory system", "The skeletal system", "The muscular system"], ans: 0, explain: "The digestive system provides digested food, which is carried by blood in the circulatory system to all parts of the body — including the muscles, brain and lungs." },
  { q: "Our eyes, ears, nose, tongue and skin are parts of the ___.", opts: ["Sensory system", "Digestive system", "Circulatory system", "Muscular system"], ans: 0, explain: "The eyes, ears, nose, tongue and skin form the parts of the sensory system. We use these to observe things around us — we see with our eyes, hear with our ears, smell with our nose, taste with our tongue and touch with our skin." },
  { q: "Which organ system protects the heart and lungs from damage?", opts: ["Skeletal system — the ribs and other bones protect these organs", "Muscular system — muscles protect the organs", "Circulatory system — blood protects the organs", "Respiratory system — the lungs protect themselves"], ans: 0, explain: "The skeletal system protects delicate organs. The ribs, for example, form a cage around the heart and lungs to protect them from damage." }
],

ch2: [
  // Chapter 10: The Digestive System in Detail
  { q: "Why do we eat food?", opts: ["To obtain energy to do work and to enable the different systems in our body to function properly", "Only to grow taller", "Only to keep warm", "To produce carbon dioxide"], ans: 0, explain: "We eat food to obtain energy to do work and to enable the different systems in our bodies to function properly." },
  { q: "Why must food be broken down before our bodies can use it?", opts: ["Food must be broken down into simpler substances before it can be absorbed into the blood and carried to different parts of the body", "Food must be made larger before the body can absorb it", "Food can be used directly without any changes", "Food must be turned into gas before the body can use it"], ans: 0, explain: "Food molecules are too large to pass into the blood. They must be broken down into simpler substances small enough to be absorbed through the walls of the small intestine into the blood." },
  { q: "What is digestion?", opts: ["The process by which food is broken down into simpler substances", "The process of breathing in and out", "The process of transporting blood around the body", "The process of removing waste from the body"], ans: 0, explain: "Digestion is the process by which food is broken down into simpler substances that the body can absorb and use." },
  { q: "What are the organs that make up the digestive system, in order?", opts: ["Mouth, gullet, stomach, small intestine, large intestine, anus", "Mouth, windpipe, lungs, stomach, anus", "Nose, gullet, stomach, large intestine, anus", "Mouth, gullet, small intestine, stomach, large intestine"], ans: 0, explain: "Food passes through the mouth, gullet, stomach, small intestine and large intestine, and waste is removed through the anus." },
  { q: "What do digestive juices do?", opts: ["They act on food and break it down into simpler substances that the body can absorb", "They help food travel faster through the digestive system", "They add flavour to the food", "They keep the food cold inside the body"], ans: 0, explain: "Digestive juices are produced in some organs of the digestive system. They act on food and break it down into simpler substances that the body can absorb." },
  { q: "Where does digestion begin?", opts: ["In the mouth", "In the stomach", "In the small intestine", "In the gullet"], ans: 0, explain: "Digestion begins in the mouth. The teeth chew food into smaller pieces and the tongue mixes the food with saliva, which contains digestive juices." },
  { q: "What do the teeth do during digestion?", opts: ["Chew food into smaller pieces, increasing the surface area that digestive juices can act on", "Absorb nutrients from the food", "Produce digestive juices", "Push food into the gullet"], ans: 0, explain: "The teeth chew food into smaller pieces. This increases the surface area of food that digestive juices can act on, speeding up digestion." },
  { q: "What does saliva do? (Choose the best answer.)", opts: ["Makes food wet and soft for swallowing, and contains digestive juices that begin to break down some food", "Kills all bacteria in the food", "Absorbs nutrients from the food directly", "Pushes food down into the stomach"], ans: 0, explain: "Saliva makes food wet and soft so it can be swallowed easily. Saliva also contains certain digestive juices that begin to break down some food into simpler substances." },
  { q: "What does the tongue do in the mouth during digestion?", opts: ["Mixes saliva with the food, and rolls the chewed food into small balls for swallowing", "Produces digestive juices", "Absorbs nutrients from the food", "Pushes food directly into the stomach"], ans: 0, explain: "The tongue mixes saliva with the food. The soft chewed food is then rolled into small balls by the tongue and swallowed." },
  { q: "Why does chewing food into smaller pieces help digestion?", opts: ["Smaller pieces have more surface area for digestive juices to act on", "Smaller pieces weigh less and travel faster", "Smaller pieces are easier to swallow and do not need digesting", "Smaller pieces go directly into the blood without being digested"], ans: 0, explain: "Chewing food into smaller pieces increases the total surface area of food that digestive juices can reach and act on. This makes digestion faster and more thorough." },
  { q: "What is the gullet?", opts: ["A tube that connects the mouth to the stomach", "A bag that produces digestive juices", "A tube that carries air to the lungs", "The opening through which waste is removed"], ans: 0, explain: "The gullet is a tube that connects the mouth to the stomach." },
  { q: "How does food move through the gullet?", opts: ["Muscles in the gullet push the chewed food down into the stomach", "Gravity alone pulls food down", "Digestive juices in the gullet push food down", "The tongue pushes food all the way down"], ans: 0, explain: "The gullet has muscles that push the chewed food down into the stomach." },
  { q: "Does the gullet produce digestive juices and digest food?", opts: ["No — the gullet only transports food; it does not digest food", "Yes — the gullet produces the most digestive juices", "Yes — the gullet digests food before the stomach does", "No — the gullet absorbs nutrients instead"], ans: 0, explain: "The gullet does not digest food. Its job is only to transport food from the mouth to the stomach. Food is digested only in the mouth, stomach and small intestine." },
  { q: "What type of organ is the stomach?", opts: ["A muscular bag that produces digestive juices", "A long tube that absorbs nutrients", "A small pouch that stores waste", "A pump that moves blood around the body"], ans: 0, explain: "The stomach is a muscular bag that produces certain digestive juices." },
  { q: "What happens to food in the stomach?", opts: ["The stomach squeezes and mixes food with digestive juices, breaking down some food into simpler substances", "The stomach absorbs all nutrients from the food", "The stomach only stores food temporarily with no chemical changes", "The stomach turns food into waste immediately"], ans: 0, explain: "Food in the stomach is squeezed and mixed with digestive juices. This helps break down some food into simpler substances. The food becomes a liquid-like substance and then moves to the small intestine." },
  { q: "What state is food in when it leaves the stomach?", opts: ["A liquid-like substance", "A solid lump", "A gas", "A dry powder"], ans: 0, explain: "After the stomach squeezes and mixes food with digestive juices, the food becomes a liquid-like substance and moves into the small intestine." },
  { q: "What is the small intestine?", opts: ["A long tube that produces digestive juices and is where digestion is completed and nutrients are absorbed", "A short wide bag that stores waste", "A tube that carries air to the lungs", "The organ where waste is formed"], ans: 0, explain: "The small intestine is a long tube that produces digestive juices. Food is further broken down here, digestion is completed, and digested food and nutrients pass through its walls into the blood." },
  { q: "Where is digestion completed?", opts: ["In the small intestine", "In the stomach", "In the mouth", "In the large intestine"], ans: 0, explain: "Digestion is completed in the small intestine. The small intestine produces digestive juices that further break down food into simpler substances." },
  { q: "How do digested nutrients reach all parts of the body after being digested in the small intestine?", opts: ["They pass through the walls of the small intestine into the blood, which carries them to all parts of the body", "They travel directly from the small intestine to the muscles without entering the blood", "They are stored in the small intestine and released slowly over time", "They travel back up to the mouth and are reswallowed"], ans: 0, explain: "Digested food and other nutrients pass through the walls of the small intestine and enter the blood. The blood then carries them to all parts of the body." },
  { q: "What happens to food that cannot be digested in the small intestine?", opts: ["It remains undigested and moves into the large intestine", "It is absorbed into the blood anyway", "It returns to the stomach to be digested again", "It is pushed back into the mouth"], ans: 0, explain: "Food that cannot be broken down into simpler substances remains undigested. It moves from the small intestine into the large intestine." },
  { q: "What does the large intestine absorb?", opts: ["Water and minerals from the undigested food", "All remaining nutrients from the food", "Digestive juices", "Carbon dioxide from the body"], ans: 0, explain: "In the large intestine, water and minerals are absorbed from the undigested food. They pass through the walls of the large intestine and enter the blood." },
  { q: "What happens to the remaining food after water and minerals are absorbed in the large intestine?", opts: ["It forms waste material that is removed from the body through the anus", "It is sent back to the small intestine for more digestion", "It is absorbed into the blood as nutrients", "It becomes gas and is breathed out"], ans: 0, explain: "After water and minerals are absorbed, the remaining undigested food becomes waste material. This waste is removed from the body through the anus." },
  { q: "In which THREE organs does digestion (breaking down of food) actually take place?", opts: ["Mouth, stomach and small intestine only", "Mouth, gullet and stomach", "Stomach, large intestine and small intestine", "Mouth, small intestine and large intestine"], ans: 0, explain: "Food is digested only in the mouth, stomach and small intestine. The gullet only transports food. The large intestine absorbs water and minerals but does not digest food." },
  { q: "A student says: 'Food is digested in every organ of the digestive system.' Is this correct?", opts: ["No — food is digested only in the mouth, stomach and small intestine; not in the gullet or large intestine", "Yes — every organ produces digestive juices", "Yes — digestion happens throughout the whole system", "No — food is only digested in the stomach"], ans: 0, explain: "This is a common misconception. Food is digested only in the mouth, stomach and small intestine. The gullet only transports food, and the large intestine only absorbs water and minerals." },
  { q: "Why should we not talk while eating?", opts: ["Small balls of food may accidentally enter our windpipe, which is very near the gullet, causing choking", "Talking makes food taste worse", "Talking makes saliva stop being produced", "Talking slows down the gullet muscles"], ans: 0, explain: "The windpipe is very near the gullet. When we talk while eating, small balls of food may accidentally enter the windpipe instead of the gullet, which can cause choking." },
  { q: "If the small intestine stops working properly, what would happen?", opts: ["Digestion would not be completed and nutrients could not be absorbed into the blood properly — the whole body would be affected", "Only the large intestine would be affected", "The stomach would do extra work to compensate", "Nothing — the gullet would take over"], ans: 0, explain: "If one organ in the digestive system does not function properly, food will not be digested or absorbed properly. This affects the rest of the body, which depends on nutrients carried by the blood." }
],

ch3: [
  // Respiratory & Circulatory Systems
  { q: "What is the main function of the respiratory system?", opts: ["To take in air (oxygen) and remove carbon dioxide from the body", "To digest food", "To pump blood around the body", "To remove solid waste"], ans: 0, explain: "The respiratory system allows us to breathe in oxygen and breathe out carbon dioxide." },
  { q: "What are the parts of the respiratory system?", opts: ["Nose, windpipe and lungs", "Heart, blood vessels and blood", "Mouth, gullet and stomach", "Skull, ribs and muscles"], ans: 0, explain: "The respiratory system is made up of the nose, windpipe and lungs." },
  { q: "What is the tube that carries air from the nose to the lungs?", opts: ["The windpipe (trachea)", "The gullet", "A blood vessel", "The small intestine"], ans: 0, explain: "The windpipe (also called the trachea) carries air from the nose and mouth down to the lungs." },
  { q: "Which gas do we breathe in that our body needs?", opts: ["Oxygen", "Carbon dioxide", "Nitrogen", "Helium"], ans: 0, explain: "We breathe in oxygen, which our body needs for energy production in cells." },
  { q: "Which gas do we breathe out as a waste product?", opts: ["Carbon dioxide", "Oxygen", "Nitrogen", "Hydrogen"], ans: 0, explain: "Carbon dioxide is a waste gas produced by our cells. It is carried to the lungs and breathed out." },
  { q: "What is the main function of the heart?", opts: ["To pump blood to all parts of the body", "To breathe in oxygen", "To digest food", "To filter waste from the blood"], ans: 0, explain: "The heart is a muscular organ that pumps blood throughout the body, delivering oxygen and nutrients to cells and carrying waste away." },
  { q: "What does blood carry TO the body cells?", opts: ["Oxygen and digested nutrients", "Carbon dioxide and waste only", "Air and undigested food", "Water only"], ans: 0, explain: "Blood carries oxygen (from the lungs) and digested nutrients (from the small intestine) to cells throughout the body." },
  { q: "What does blood carry AWAY from the body cells?", opts: ["Carbon dioxide and other waste products", "Oxygen and nutrients", "Food and minerals", "Saliva"], ans: 0, explain: "Blood picks up carbon dioxide and other waste products from cells and carries them to the lungs and other organs for removal." },
  { q: "How are the respiratory system and circulatory system connected?", opts: ["The lungs pass oxygen into the blood; the heart pumps this oxygen-rich blood to all body parts", "The heart breathes air in for the lungs", "The lungs pump blood around the body", "They are not connected"], ans: 0, explain: "The respiratory and circulatory systems work together: oxygen enters the blood in the lungs, and the heart pumps this oxygen-rich blood to all parts of the body." },
  { q: "Which of the following is NOT part of the respiratory system?", opts: ["Heart", "Lungs", "Windpipe", "Nose"], ans: 0, explain: "The heart is part of the circulatory system, not the respiratory system. The respiratory system is made up of the nose, windpipe and lungs." },
  { q: "After exercise, Mei Ling breathes faster. Why?", opts: ["Her body needs more oxygen and needs to remove more carbon dioxide from her working muscles", "She is trying to cool herself down", "Her lungs have grown smaller", "Her heart has stopped beating"], ans: 0, explain: "During exercise, muscles use more oxygen and produce more carbon dioxide. Breathing faster brings in more oxygen and removes more carbon dioxide." },
  { q: "After exercise, why does the heart beat faster?", opts: ["To pump more blood carrying oxygen and nutrients to the muscles that need them", "To digest food more quickly", "To make the lungs smaller", "To slow down breathing"], ans: 0, explain: "During exercise, muscles need more oxygen. The heart beats faster to pump more oxygen-rich blood to the muscles." },
  { q: "What would happen if the windpipe was blocked?", opts: ["Air could not reach the lungs and the person could not breathe", "Food could not reach the stomach", "Blood could not flow to the heart", "The person could not see"], ans: 0, explain: "If the windpipe is blocked, air cannot travel to the lungs. The person would not be able to breathe." },
  { q: "Why is the heart considered a very important organ?", opts: ["Without the heart pumping blood, oxygen and nutrients cannot reach our body cells", "The heart helps us chew food", "The heart helps us breathe in air", "The heart produces oxygen"], ans: 0, explain: "The heart pumps blood that carries oxygen and nutrients to every cell in the body. Without it, cells would not receive what they need to function." },
  { q: "How is the windpipe different from the gullet?", opts: ["The windpipe carries air to the lungs; the gullet carries food to the stomach. They are located next to each other.", "The gullet carries air; the windpipe carries food", "Both carry food to the stomach", "Both carry air to the lungs"], ans: 0, explain: "The windpipe (trachea) is an air tube leading to the lungs. The gullet (oesophagus) is a food tube leading to the stomach. They are located next to each other in the throat — which is why we can choke if food enters the windpipe." },
  { q: "Why do we feel out of breath after running up many flights of stairs?", opts: ["Our muscles used up a lot of oxygen and produced a lot of carbon dioxide, so we breathe faster to exchange gases", "Our stomach needs more food", "Our small intestine stopped absorbing nutrients", "Our lungs shrank"], ans: 0, explain: "Running uses a lot of energy. Muscles need more oxygen and produce more carbon dioxide. We breathe faster and harder to meet this increased demand." },
  { q: "Where does the exchange of oxygen and carbon dioxide take place?", opts: ["In the lungs", "In the heart", "In the stomach", "In the windpipe"], ans: 0, explain: "Gas exchange occurs in the lungs, where oxygen from inhaled air enters the blood and carbon dioxide from the blood is released to be breathed out." }
],

ch4: [
  // Plant Transport System
  { q: "What is the main function of the roots of a plant?", opts: ["To absorb water and minerals from the soil, and to anchor the plant in the ground", "To make food for the plant", "To carry out photosynthesis", "To produce flowers and seeds"], ans: 0, explain: "Roots absorb water and minerals from the soil and hold the plant firmly in the ground." },
  { q: "What is the function of the stem in a plant?", opts: ["To support the plant and transport water and nutrients between the roots and leaves", "To absorb water from the soil", "To make food using sunlight", "To produce seeds"], ans: 0, explain: "The stem supports the plant and holds up the leaves. It also transports water from the roots to the leaves and carries food made in the leaves to other parts of the plant." },
  { q: "Which part of the plant makes food?", opts: ["Leaves", "Roots", "Stem", "Flowers"], ans: 0, explain: "The leaves make food for the plant through photosynthesis, using sunlight, water and carbon dioxide." },
  { q: "What do leaves need to make food?", opts: ["Sunlight, water and carbon dioxide", "Soil, oxygen and darkness", "Minerals, wind and shade", "Fertiliser, oxygen and heat"], ans: 0, explain: "Leaves use sunlight (energy), water (from roots) and carbon dioxide (from air) to make food through photosynthesis." },
  { q: "Water travels from the roots to the leaves through the ___.", opts: ["Stem", "Flower", "Fruit", "Seed"], ans: 0, explain: "Water absorbed by the roots is transported upward through tubes in the stem to reach the leaves and other parts of the plant." },
  { q: "Which part of a plant anchors it firmly in the soil?", opts: ["Roots", "Stem", "Leaves", "Flowers"], ans: 0, explain: "Roots grow into the soil and hold the plant firmly in place, preventing it from being blown away." },
  { q: "What would happen to a plant if its roots were damaged?", opts: ["The plant would not be able to absorb enough water and minerals and would wilt", "The plant would make more food", "The plant would grow taller", "Nothing would change"], ans: 0, explain: "Damaged roots cannot absorb water and minerals properly. The plant would wilt and eventually die." },
  { q: "A plant is left without water for several days. What will happen?", opts: ["The plant will wilt", "The plant will grow faster", "The plant will produce more flowers", "Nothing will happen"], ans: 0, explain: "Without water, the plant cannot maintain firm cells. It will wilt." },
  { q: "Which of these is NOT a function of the roots?", opts: ["Making food for the plant", "Absorbing water from the soil", "Absorbing minerals from the soil", "Anchoring the plant in the soil"], ans: 0, explain: "Roots do not make food. Food is made by the leaves through photosynthesis. Roots absorb water, absorb minerals and anchor the plant." },
  { q: "A student placed a white flower in red-coloured water. After a few hours, the petals turned red. What does this show?", opts: ["Water (and dissolved substances) is transported from the roots through the stem to all parts of the plant", "The flower produced its own red colour", "The petals absorbed colour from the air", "The roots changed the colour of the petals"], ans: 0, explain: "The coloured water was absorbed by the roots and transported up through the stem to the petals, showing how water moves through a plant's transport system." },
  { q: "What would happen to a plant if its stem was cut through?", opts: ["Water and nutrients could not be transported between the roots and leaves — the plant would die", "The plant would absorb more water through its leaves", "The leaves would make more food", "The flowers would bloom faster"], ans: 0, explain: "If the stem is cut, the transport system is broken. Water cannot reach the leaves and food cannot reach the roots. The plant would die." },
  { q: "Which gas is released by leaves during photosynthesis?", opts: ["Oxygen", "Carbon dioxide", "Nitrogen", "Hydrogen"], ans: 0, explain: "When leaves make food through photosynthesis, oxygen is released as a by-product. This is the oxygen that animals and humans breathe." },
  { q: "How is the function of the stem similar to the function of blood vessels in humans?", opts: ["Both transport substances around the body of the organism", "Both make food", "Both absorb water from outside", "Both produce oxygen"], ans: 0, explain: "Both the stem (in plants) and blood vessels (in humans) form a transport system that moves essential substances around the organism." },
  { q: "Why does a plant need minerals from the soil?", opts: ["To grow healthily — minerals are needed for the plant to make green pigment and grow well", "To make the soil softer", "To attract insects to its flowers", "To make the stem heavier"], ans: 0, explain: "Plants need minerals (such as nitrogen and magnesium) absorbed by the roots. Without minerals, plants cannot grow healthily and their leaves may turn yellow." },
  { q: "A potted plant is healthy but the soil has no minerals. Plenty of water and sunlight are given. What is most likely to happen?", opts: ["The plant will not grow well and may have yellow leaves — minerals are essential even if water and sunlight are present", "The plant will grow much taller than usual", "The plant will produce many more flowers", "Nothing will change"], ans: 0, explain: "Minerals are essential for healthy growth. Without minerals, the plant cannot grow properly even with sufficient water and sunlight." }
],

ch5: [
  // Electrical Circuits
  { q: "What is needed to make a complete electrical circuit?", opts: ["A battery, wires, and a device like a bulb, all connected in a closed loop", "Only a battery", "Only a bulb and wire", "A switch alone"], ans: 0, explain: "A complete circuit needs a source of electricity (battery), connecting wires and a device (like a bulb), all connected in a closed loop with no gaps." },
  { q: "What is a closed circuit?", opts: ["A circuit with no gaps, so electricity can flow through it", "A circuit with a gap so electricity cannot flow", "A circuit with no battery", "A circuit with no wires"], ans: 0, explain: "In a closed circuit there are no gaps, so electricity can flow continuously from the battery through the wires and back." },
  { q: "What is an open circuit?", opts: ["A circuit with a gap, so electricity cannot flow", "A circuit where the bulb lights up", "A circuit with extra batteries", "A circuit with no switch"], ans: 0, explain: "An open circuit has a gap or break which stops electricity from flowing. The bulb will not light up." },
  { q: "What is the function of a switch in a circuit?", opts: ["To open or close the circuit, controlling whether electricity flows", "To make the bulb brighter", "To replace the battery", "To produce electricity"], ans: 0, explain: "A switch opens or closes a circuit. When closed, electricity flows. When open, the circuit is broken and electricity stops." },
  { q: "What is a conductor?", opts: ["A material that allows electricity to flow through it", "A material that blocks electricity", "A type of battery", "A type of switch"], ans: 0, explain: "A conductor allows electricity to pass through it easily. Most metals are good conductors." },
  { q: "What is an insulator?", opts: ["A material that does not allow electricity to flow through it", "A material that helps electricity flow easily", "A type of wire", "A type of bulb"], ans: 0, explain: "An insulator does not allow electricity to pass through it. Rubber, plastic and wood are common insulators." },
  { q: "Which of the following is a conductor of electricity?", opts: ["Metal spoon", "Rubber band", "Plastic ruler", "Wooden stick"], ans: 0, explain: "A metal spoon is a conductor — metals allow electricity to flow through them." },
  { q: "Which of the following is an insulator?", opts: ["Plastic comb", "Iron nail", "Copper wire", "Aluminium foil"], ans: 0, explain: "A plastic comb is an insulator — plastic does not allow electricity to flow through it." },
  { q: "In a series circuit with one battery and one bulb, what happens if you add one more battery?", opts: ["The bulb becomes brighter", "The bulb becomes dimmer", "The bulb stays the same", "The bulb will not light up"], ans: 0, explain: "Adding more batteries increases the electrical energy in the circuit, making the bulb glow brighter." },
  { q: "In a series circuit with one battery and one bulb, what happens if you add one more bulb?", opts: ["Both bulbs will be dimmer than the single bulb was", "Both bulbs will be brighter", "Only one bulb lights up", "The battery stops working"], ans: 0, explain: "In a series circuit, adding more bulbs means the same electrical energy is shared among them, so each bulb is dimmer." },
  { q: "Why are the wires in electrical cables covered with plastic?", opts: ["Plastic is an insulator that prevents electric shocks", "Plastic helps electricity flow faster", "Plastic makes the wire look colourful", "Plastic is a conductor"], ans: 0, explain: "Plastic is an insulator. Covering wires with plastic prevents people from getting electric shocks when they touch the cable." },
  { q: "In a series circuit, if one bulb burns out, what happens to the other bulbs?", opts: ["All the other bulbs go out — the circuit is broken", "The other bulbs become brighter", "Nothing happens to the other bulbs", "The other bulbs start blinking"], ans: 0, explain: "In a series circuit, all components are in one loop. If one bulb burns out, the circuit is broken and all other bulbs go out." },
  { q: "What is a series circuit?", opts: ["A circuit where all components are connected in a single loop", "A circuit where components are connected in separate loops", "A circuit with no battery", "A circuit with only switches"], ans: 0, explain: "In a series circuit, all the components (batteries, bulbs, switches) are connected one after another in a single loop." },
  { q: "Which of the following will NOT allow electricity to flow through it?", opts: ["Rubber eraser", "Paper clip (metal)", "Copper coin", "Steel key"], ans: 0, explain: "A rubber eraser is an insulator and does not allow electricity to flow through it." },
  { q: "Why do electricians wear rubber gloves?", opts: ["Rubber is an insulator that protects them from electric shocks", "Rubber helps them conduct electricity better", "Rubber makes their hands warmer", "Rubber helps them grip wires"], ans: 0, explain: "Rubber is an insulator. Wearing rubber gloves prevents electricity from flowing through the electrician's body, protecting them from electric shocks." }
],

tricky: [
  { q: "Which organ is shared as a passageway by both the digestive system and the respiratory system?", opts: ["The mouth and throat area — food passes to the gullet, air passes to the windpipe", "The stomach", "The lungs", "The small intestine"], ans: 0, explain: "The mouth and throat are shared by both systems. Food passes through on its way to the gullet, and air passes through on its way to the windpipe. They are located next to each other, which is why we can choke." },
  { q: "A plant is placed in a completely dark room but is given plenty of water and minerals. What will eventually happen?", opts: ["The plant will die — without sunlight the leaves cannot make food through photosynthesis", "The plant will grow very well", "The plant will produce more flowers", "Nothing will happen since it has water and minerals"], ans: 0, explain: "Leaves need sunlight to make food through photosynthesis. Without sunlight, the plant cannot make food and will eventually die, even with water and minerals." },
  { q: "Ali swallowed his food without chewing it properly. What problem might this cause for digestion?", opts: ["The food is in large pieces with less surface area, so digestive juices cannot act on it as effectively — digestion is slower and less complete", "The food will be absorbed faster because it is bigger", "The gullet will chew the food instead", "The stomach will not receive any food"], ans: 0, explain: "Chewing increases surface area for digestive juices to act on. If food is not chewed properly, it is in larger pieces with less surface area, making digestion slower and less thorough." },
  { q: "Tom ate a sandwich. In what order did it travel through his digestive system? (A) Stomach  (B) Gullet  (C) Small intestine  (D) Mouth  (E) Large intestine", opts: ["D → B → A → C → E", "D → A → B → C → E", "B → D → A → E → C", "A → B → D → C → E"], ans: 0, explain: "Food goes from the mouth (D), down the gullet (B), into the stomach (A), through the small intestine (C), and finally into the large intestine (E) before waste is removed through the anus." },
  { q: "Ahmad tested a coin, a straw, a paper clip and an eraser in a circuit. Which two completed the circuit and lit the bulb?", opts: ["Coin and paper clip — both are metals (conductors)", "Straw and eraser — both are insulators", "Coin and eraser", "Straw and paper clip"], ans: 0, explain: "A coin (metal) and a paper clip (metal) are conductors and allow electricity to flow, completing the circuit. The straw (plastic) and eraser (rubber) are insulators." },
  { q: "A wilted plant is given water. What will happen?", opts: ["The plant will recover and become firm again — water fills the cells and makes them firm", "The plant will continue to wilt", "The plant will lose all its leaves", "Nothing will change"], ans: 0, explain: "When a wilted plant receives water, its cells absorb the water and become firm (turgid) again, causing the plant to stand upright and recover." },
  { q: "In a series circuit with 2 batteries and 1 bulb, the bulb is bright. What happens if one battery is removed?", opts: ["The bulb becomes dimmer — less electrical energy is available", "The bulb becomes brighter", "The bulb goes out completely", "The bulb starts blinking"], ans: 0, explain: "Removing one battery reduces the electrical energy in the circuit. The bulb still lights up but is dimmer." },
  { q: "The digestive system provides food for the body, but the circulatory system is needed for this food to reach muscles and the brain. What does this tell us about body systems?", opts: ["Body systems are interconnected — the digestive system and circulatory system must work together for nutrients to reach all parts of the body", "The two systems compete with each other", "Each system works completely independently", "Only the digestive system matters for getting energy to muscles"], ans: 0, explain: "All body systems are interconnected. The digestive system breaks down and absorbs food, but the circulatory system must transport those nutrients to the muscles, brain and other organs." },
  { q: "A doctor tells a patient that her large intestine is not working properly. Which of the following would most likely be a problem?", opts: ["Too much water would remain in the waste, causing loose stools (diarrhoea)", "Digestion of food would not be completed", "Nutrients would not be absorbed into the blood", "Food would not be broken down in the mouth"], ans: 0, explain: "The large intestine absorbs water from undigested food. If it does not work properly, too much water remains in the waste, resulting in diarrhoea (loose or liquid stools)." },
  { q: "Why should leaves be clean and not covered in dust for a plant to grow well?", opts: ["Dust blocks sunlight and blocks the tiny openings in leaves, preventing carbon dioxide from entering — the plant cannot make food efficiently", "Dust adds minerals to the leaves", "Dust prevents water from evaporating, which is helpful", "Dust has no effect on leaves"], ans: 0, explain: "Leaves need sunlight and carbon dioxide to make food. Dust blocks sunlight and can block the tiny openings in leaves, reducing the plant's ability to photosynthesise." }
],

hard: [
  { q: "Which system absorbs nutrients that are then transported by another system to the rest of the body?", opts: ["Digestive system absorbs nutrients in the small intestine; circulatory system transports them in the blood", "Respiratory system absorbs nutrients; digestive system transports them", "Circulatory system absorbs nutrients; respiratory system transports them", "Digestive system both absorbs and transports nutrients on its own"], ans: 0, explain: "The digestive system breaks down food and nutrients are absorbed through the walls of the small intestine into the blood. The circulatory system then carries these nutrients in the blood to all body cells." },
  { q: "During vigorous exercise, both breathing rate and heart rate increase. Why?", opts: ["Working muscles need more oxygen and produce more carbon dioxide — faster breathing brings in more oxygen, and a faster heartbeat delivers it quickly to muscles", "The body needs to digest food faster", "The lungs need to shrink to save energy", "The stomach needs more blood to digest food"], ans: 0, explain: "Exercise muscles need more oxygen and produce more carbon dioxide. Faster breathing exchanges these gases faster. A faster heartbeat pumps more oxygen-rich blood to the muscles quickly." },
  { q: "In a series circuit, two identical bulbs are lit. One bulb is then unscrewed. What happens to the other bulb and why?", opts: ["It goes out — unscrewing one bulb breaks the single loop of a series circuit, so no electricity can flow", "It becomes twice as bright — all the energy goes to it", "It stays the same brightness", "It starts to blink"], ans: 0, explain: "In a series circuit, all components share one loop. Removing one bulb breaks the circuit completely, so no electricity flows and the remaining bulb goes out." },
  { q: "A farmer notices his crop leaves are turning yellow even though there is enough sunlight and water. What is the most likely cause?", opts: ["The roots are not absorbing enough minerals from the soil — minerals are needed for the plant to make green pigment and grow healthily", "The leaves are getting too much sunlight", "The stem is producing too much food", "The plant has too many flowers"], ans: 0, explain: "Yellow leaves usually indicate a lack of minerals (especially those needed for green pigment). Roots may not be absorbing enough minerals, possibly because the soil lacks them." },
  { q: "If a person's small intestine were much shorter than normal, what would happen?", opts: ["Fewer nutrients would be absorbed into the blood — less surface area means less absorption", "Food would be digested faster", "The person would not need to eat", "The stomach would absorb nutrients instead"], ans: 0, explain: "A shorter small intestine has less surface area for nutrients to pass through its walls into the blood. The person would absorb fewer nutrients and would be malnourished." },
  { q: "How is the transport of water in plants similar to the transport of blood in humans?", opts: ["Both use a network of tubes to carry substances to all parts of the organism", "Both use a heart to pump fluids", "Both transport only oxygen", "Both systems use lungs"], ans: 0, explain: "Plants use tubes in the stem (xylem) to transport water. Humans use blood vessels. Both form a network that delivers essential substances throughout the organism." },
  { q: "Explain why the circulatory system is important for BOTH the digestive system and the respiratory system.", opts: ["Blood carries nutrients from the digestive system (small intestine) AND oxygen from the respiratory system (lungs) to every cell in the body", "Blood only carries oxygen, not nutrients", "The circulatory system only works with the respiratory system", "The circulatory system only helps with digestion"], ans: 0, explain: "The circulatory system links both systems: it carries oxygen obtained in the lungs (respiratory) and nutrients absorbed in the small intestine (digestive) to every cell in the body." },
  { q: "A student builds a series circuit with a battery, a switch, a bulb and a buzzer. The switch is closed. What happens, and what happens if the buzzer breaks?", opts: ["Both the bulb and buzzer work; if the buzzer breaks the circuit is open and the bulb also goes out", "Only the bulb works; the buzzer has no effect", "Only the buzzer works; the bulb goes out", "Both stop working as soon as the switch is closed"], ans: 0, explain: "In a series circuit, all devices are in one loop. When the switch is closed, both the bulb and buzzer work. If the buzzer breaks, the circuit is broken and the bulb also goes out." },
  { q: "A garden plant wilts badly by Friday even though it is in full sunlight. The soil is completely dry. Which part of the plant system has failed, and why?", opts: ["The roots cannot absorb water because there is no water in the soil — without water, cells lose firmness and the plant wilts", "The leaves have stopped making food", "The stem has grown too tall and cannot support the plant", "The flowers have used up all the water"], ans: 0, explain: "Without water in the soil, the roots cannot absorb any water. Without water reaching the leaves and cells, the plant cannot stay turgid and wilts." }
],

compare: [
  { q: "How is the gullet different from the windpipe?", opts: ["The gullet carries food from the mouth to the stomach; the windpipe carries air from the nose to the lungs", "The gullet carries air; the windpipe carries food", "Both carry food to the stomach", "Both carry air to the lungs"], ans: 0, explain: "The gullet is a food tube connecting the mouth to the stomach. The windpipe is an air tube connecting the nose and mouth to the lungs. They are located next to each other, which is why food can accidentally enter the windpipe when we talk while eating." },
  { q: "How is the function of the small intestine different from the large intestine?", opts: ["Small intestine: digestion is completed and nutrients are absorbed into the blood; Large intestine: water and minerals are absorbed from undigested food", "Small intestine absorbs water; large intestine absorbs nutrients", "Both have the same role — they both digest food", "Neither absorbs anything — both only transport food"], ans: 0, explain: "The small intestine completes digestion and absorbs digested nutrients into the blood. The large intestine does not digest food — it absorbs water and minerals from undigested food and forms waste." },
  { q: "How is the function of the heart different from the function of the lungs?", opts: ["The heart pumps blood around the body; the lungs take in oxygen and remove carbon dioxide", "The heart takes in oxygen; the lungs pump blood", "Both organs pump blood", "Both organs exchange gases"], ans: 0, explain: "The heart is a pump that circulates blood. The lungs are where oxygen enters the blood and carbon dioxide is removed. They work together but have different roles." },
  { q: "How are conductors and insulators different?", opts: ["Conductors allow electricity to flow through them; insulators do not", "Insulators allow electricity to flow; conductors do not", "Both allow electricity to flow", "Neither allows electricity to flow"], ans: 0, explain: "Conductors (like metals) let electricity pass through easily. Insulators (like rubber and plastic) block the flow of electricity." },
  { q: "How is the role of roots in a plant different from the role of the leaves?", opts: ["Roots absorb water and minerals from the soil; leaves use sunlight, water and carbon dioxide to make food", "Roots make food; leaves absorb water", "Both absorb water from the soil", "Both make food using sunlight"], ans: 0, explain: "Roots absorb water and minerals, and anchor the plant. Leaves make food through photosynthesis using sunlight, water and carbon dioxide." },
  { q: "How is an open circuit different from a closed circuit?", opts: ["Open circuit: has a gap so electricity cannot flow; Closed circuit: no gap so electricity flows continuously", "Closed circuit has a gap; open circuit has no gap", "Both allow electricity to flow", "Neither allows electricity to flow"], ans: 0, explain: "An open circuit has a break or gap that stops electricity from flowing. A closed circuit is a complete loop with no gaps, allowing electricity to flow continuously." },
  { q: "How is adding more batteries different from adding more bulbs in a series circuit?", opts: ["More batteries: bulbs get brighter (more energy); More bulbs: each bulb gets dimmer (energy is shared)", "More batteries: bulbs get dimmer; More bulbs: each bulb gets brighter", "Both make bulbs brighter", "Both make bulbs dimmer"], ans: 0, explain: "More batteries add more electrical energy to the circuit, making bulbs brighter. More bulbs share the same energy, making each bulb dimmer." },
  { q: "Compare the digestive system of a human and the transport system of a plant. What is similar?", opts: ["Both process and transport nutrients/substances to all parts of the organism so it can function and grow", "Both use blood to carry substances", "Both use digestive juices to break down food", "They have nothing in common"], ans: 0, explain: "Both systems ensure nutrients reach all parts of the organism. The digestive system breaks down food and the circulatory system delivers nutrients to human cells. The plant transport system moves water and food to plant cells." },
  { q: "How is a man-made system (like a torch) similar to a natural system (like the human body)?", opts: ["Both are made of two or more parts that work together; if one part fails, the system cannot carry out its function properly", "Man-made systems always have more parts than natural systems", "Natural systems never fail; only man-made systems can break", "They are completely different and share nothing in common"], ans: 0, explain: "Both man-made and natural systems are made of two or more parts working together. In both, if one part is damaged or does not work, the system cannot carry out its function properly." },
  { q: "How is the function of the stomach different from the function of the gullet during digestion?", opts: ["The stomach digests food (produces digestive juices, squeezes and mixes food); the gullet only transports food and does not digest it", "The gullet digests food; the stomach only stores it", "Both digest food equally", "Both only transport food without any digestion"], ans: 0, explain: "The stomach actively digests food by producing digestive juices and squeezing/mixing the food. The gullet has no digestive role — it only pushes food from the mouth down to the stomach." }
]

};
